-- RealVolt Fix 052 — run ONLY after 050 on a backed-up staging database.
-- Entire file is ONE DO statement, from DO $rv052$ to END $rv052$;
-- Corrects seller/ buyer side forms, resets only clearly invalid prior verifications,
-- and blocks future matching of known-unrelated administrative reports.
DO $rv052$
DECLARE revoked_count integer := 0;
BEGIN
 EXECUTE $rv052_tx$create or replace function public.rv_tx_action(p_deal uuid,p_action text,p_date date default null,p_document uuid default null,p_note text default '') returns void language plpgsql security definer set search_path='' as $$ declare d public.deal_files; doc public.deal_documents; agent boolean; office boolean; today date:=(now() at time zone 'America/Vancouver')::date; v_requirement_label text; begin select * into d from public.deal_files where id=p_deal for update; if not found or d.brokerage_id is distinct from public.current_brokerage() or auth.uid() is null then raise exception 'File unavailable';end if; agent:=d.user_id=auth.uid();office:=public.can_review_deal(d.user_id);if not (agent or office) then raise exception 'File unavailable';end if; if p_document is not null then select * into doc from public.deal_documents where id=p_document and deal_id=d.id;if not found or lower(doc.name) not like '%.pdf' or not exists(select 1 from storage.objects o where o.bucket_id='transaction-files' and o.name=doc.path) then raise exception 'Select an uploaded PDF from this transaction';end if;end if; perform set_config('realvolt.lifecycle_rpc','yes',true); if p_action='seen' and office and d.review_status='Submitted' then if not exists(select 1 from public.rv_transaction_notifications n where n.deal_id=d.id and n.recipient_id=d.user_id and n.message='Back Office opened your file' and n.created_at>=d.updated_at) then perform public.rv_tx_notice(d,'agent','Back Office opened your file');end if; elsif p_action='reopen' and agent and d.kind='Sale' and d.review_status='Approved' and (d.rv_stage is null or d.rv_stage='Accepted offer') then update public.deal_files set review_status='Changes requested' where id=d.id; elsif p_action='firm' and agent and d.kind='Sale' and d.review_status in ('Draft','Submitted','Changes requested','Approved') and (d.rv_stage is null or d.rv_stage='Accepted offer') then if p_document is null or p_date is null or p_date>today or d.contract_date is null or p_date<d.contract_date or d.completion_date is null or d.completion_date<p_date or d.sale_price is null or d.sale_price<=0 or btrim(d.buyer_name)='' or btrim(d.seller_name)='' then raise exception 'Enter the signed subject removal PDF, actual firm date, contract/completion dates, buyer and seller names, and sale price';end if; if not exists(select 1 from public.transaction_reviewers r join public.brokerage_members m on m.user_id=r.admin_id and m.brokerage_id=d.brokerage_id and m.role='admin' where r.agent_id=d.user_id) then raise exception 'No assigned reviewer';end if; if exists (select 1 from (values ('Signed subject removal / unconditional contract'),('Title search'),('Property Disclosure Statement (PDS)'),('Deposit cheque copy / deposit receipt'),('Trade record sheet'),(case when d.representation='listing' then 'Receipt of funds' else 'Sale report form' end)) needed(label) left join public.deal_requirements r on r.deal_id=d.id and r.label=needed.label where r.document_id is null or coalesce(r.rv_waived,false)) then raise exception 'Attach subject removal, title search, PDS, deposit cheque copy, trade record and the required seller/buyer document before marking the sale firm';end if; insert into public.deal_requirements(deal_id,label,document_id,verified) values(d.id,'Signed subject removal / unconditional contract',p_document,false) on conflict(deal_id,label) do update set document_id=excluded.document_id,verified=false; update public.deal_files set rv_stage='Sold',rv_firm_date=p_date,review_status='Submitted',rv_post_firm_details_confirmed=false where id=d.id; perform public.rv_tx_notice(d,'office','Firm sale submitted — verify subject removal'); elsif p_action in ('extend_subject','extend_completion','collapse') and agent and d.kind='Sale' and ((p_action in ('extend_subject','collapse') and (d.rv_stage is null or d.rv_stage='Accepted offer') and d.review_status in ('Draft','Submitted','Changes requested','Approved')) or (p_action='extend_completion' and d.rv_stage='Sold' and d.review_status='Approved')) then if p_action<>'collapse' and (p_document is null or p_date is null) then raise exception 'Upload and select the signed amendment PDF and revised date';end if; if p_action='extend_subject' and ((d.rv_stage is not null and d.rv_stage<>'Accepted offer') or d.contract_date is null or p_date<=coalesce(d.subject_date,d.contract_date) or (d.completion_date is not null and p_date>d.completion_date)) then raise exception 'Enter a later subject date before completion';end if; if p_action='extend_completion' and p_date<=coalesce(d.completion_date,d.contract_date) then raise exception 'Enter a later completion date';end if; if p_action<>'collapse' then v_requirement_label:=case p_action when 'extend_subject' then 'Subject extension' else 'Completion extension' end||' — '||p_document::text; insert into public.deal_requirements(deal_id,label,document_id,rv_phase,rv_required) values(d.id,v_requirement_label,p_document,case when p_action='extend_completion' then 'completion' else 'firm' end,true) on conflict do nothing;end if; update public.deal_files set subject_date=case when p_action='extend_subject' then p_date else subject_date end,completion_date=case when p_action='extend_completion' then p_date else completion_date end,rv_stage=case when p_action='collapse' then 'Collapsed' else rv_stage end,review_status='Submitted' where id=d.id; if p_action='collapse' then insert into public.transaction_audit_events(deal_id,actor_id,action,new_values) values(d.id,auth.uid(),'Offer collapsed',jsonb_build_object('stage','Collapsed','no_document_required',true)); perform public.rv_tx_notice(d,'office','Offer collapsed — file closed');elsif p_action='extend_subject' then insert into public.transaction_audit_events(deal_id,actor_id,action,new_values) values(d.id,auth.uid(),'Subject date extended',jsonb_build_object('subject_date',p_date,'document_id',p_document)); perform public.rv_tx_notice(d,'office','Subject extension submitted — review revised date');end if; elsif p_action in ('terminate','extend_listing') and agent and d.kind='Listing' and d.review_status='Approved' then if p_document is null or p_date is null or (p_action='terminate' and (btrim(p_note)='' or p_date>today)) then raise exception 'Select signed PDF, date and termination reason where applicable';end if; if exists(select 1 from public.deal_files s where s.parent_listing_id=d.id and s.rv_stage is distinct from 'Collapsed') then raise exception 'Resolve linked sale before amending listing';end if; if p_action='extend_listing' and (p_date<=today or exists(select 1 from public.listing_terms t where t.deal_id=d.id and (t.termination_date is not null or t.expiry_date>=p_date))) then raise exception 'Choose a later expiry date for an unterminated listing';end if; insert into public.deal_requirements(deal_id,label,document_id) values(d.id,(case when p_action='terminate' then 'Termination' else 'Listing extension' end)||' — '||p_document::text,p_document) on conflict do nothing; if p_action='terminate' then update public.listing_terms set termination_date=p_date,termination_reason=p_note where deal_id=d.id;else update public.listing_terms set expiry_date=p_date where deal_id=d.id;end if; update public.deal_files set review_status='Submitted' where id=d.id; elsif p_action='complete' and office and d.rv_stage='Sold' and d.review_status='Approved' then if not d.rv_post_firm_details_confirmed or d.buyer_lawyer_id is null or d.seller_lawyer_id is null then raise exception 'Save and confirm both lawyer contacts, commission and deposit details after firm sale before legal completion'; end if; if p_document is null or p_date is null or p_date>today or p_date<d.rv_firm_date then raise exception 'Select lawyer completion letter PDF and actual completion date';end if; update public.deal_files set rv_stage='Completed',rv_completed_date=p_date,rv_completion_letter=p_document where id=d.id; perform public.rv_tx_notice(d,'agent','Legal completion confirmed'); elsif p_action='funds' and office and d.rv_stage='Completed' then if btrim(p_note)='' then raise exception 'Record verified receipt / bank reference';end if; update public.deal_files set rv_funds_verified=true where id=d.id; insert into public.transaction_audit_events(deal_id,actor_id,action,new_values) values(d.id,auth.uid(),'Commission funds verified',jsonb_build_object('reference',p_note)); elsif p_action='missing' and office and d.review_status in ('Submitted','Approved') then if btrim(p_note)='' then raise exception 'Enter missing documents';end if;perform public.rv_tx_notice(d,'agent','Documents required: '||p_note); elsif p_action='archive' and office and d.rv_stage='Completed' then if not exists(select 1 from public.agent_payouts where deal_id=d.id and status='Paid') or exists(select 1 from public.deal_requirements where deal_id=d.id and not verified) then raise exception 'Verify final documents and record agent payment first';end if; update public.deal_files set rv_stage='Archived' where id=d.id; else raise exception 'Action is not available for this file or role';end if; perform set_config('realvolt.lifecycle_rpc','no',true); end $$$rv052_tx$;
 EXECUTE $rv052_seed$CREATE OR REPLACE FUNCTION public.rv_seed_brokerage_compliance(p_brokerage uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN INSERT INTO public.rv_compliance_templates(brokerage_id,kind,phase,representation,label,required,sort_order) SELECT p_brokerage,v.kind,v.phase,v.representation,v.label,v.required,v.sort_order FROM (VALUES ('Listing','listing','any','Signed listing contract',true,10), ('Listing','listing','any','MLS listing sheet / listing details',true,20), ('Listing','listing','any','Disclosure (listing)',true,30), ('Listing','listing','any','FINTRAC identity verification',true,40), ('Listing','listing','any','Listing addendum (if applicable)',false,50), ('Sale','offer','any','Signed purchase and sale contract',true,10), ('Sale','offer','listing','Commission disclosure',true,20), ('Sale','offer','selling','Disclosure of services / representation',true,20), ('Sale','offer','selling','FINTRAC identity verification — buyer(s)',true,30), ('Sale','offer','any','Contract addendum (if applicable)',false,40), ('Sale','firm','any','Signed subject removal / unconditional contract',true,10), ('Sale','firm','listing','Trade record sheet',true,20), ('Sale','firm','selling','Trade record sheet',true,25), ('Sale','firm','selling','Sale report form',true,27), ('Sale','firm','listing','Receipt of funds',true,30), ('Sale','firm','selling','Deposit cheque copy / deposit receipt',true,20), ('Sale','firm','any','Subject extension or other addendum (if applicable)',false,40), ('Sale','completion','any','Lawyer completion letter',true,10), ('Sale','completion','any','Brokerage completion confirmation (PDF)',true,20), ('Sale','completion','any','Commission Instruction Report — CIR (PDF)',true,30), ('Sale','completion','any','Internal commission payable statement (PDF)',true,40) ) v(kind,phase,representation,label,required,sort_order) ON CONFLICT(brokerage_id,kind,phase,representation,label) DO NOTHING; END; $$$rv052_seed$;

  -- Revoke "verified" on clearly unrelated administrative PDFs, leave links for review.
  UPDATE public.deal_requirements r
     SET verified = false, rv_verified_by = NULL, rv_verified_at = NULL
    FROM public.deal_documents f
   WHERE f.id = r.document_id AND r.verified = true
     AND coalesce(r.rv_phase,'other') IN ('offer','firm','completion')
     AND (
       f.name ~* '(agentexpensesbydate|agentgstreport|cheque[_ .-]*alignment|payroll[_ .-]*report|bank[_ .-]*statement)'
       OR (f.name ~* 'internal[_ .-]*commission[_ .-]*(payable[_ .-]*)?statement'
           AND lower(r.label) <> 'internal commission payable statement (pdf)')
       OR (f.name ~* 'commission[_ .-]*instruction[_ .-]*report'
           AND lower(r.label) NOT IN ('commission instruction report — cir (pdf)', 'commission instruction report (cir)'))
       OR (f.name ~* 'letter[_ .-]*to[_ .-]*complete'
           AND lower(r.label) <> 'lawyer completion letter')
       OR (f.name ~* 'brokerage[_ .-]*completion[_ .-]*confirmation'
           AND lower(r.label) <> 'brokerage completion confirmation (pdf)')
     );
  GET DIAGNOSTICS revoked_count = ROW_COUNT;
  RAISE NOTICE 'RealVolt 052: revoked % suspect compliance verifications; documents were retained.', revoked_count;

  -- Preserve obsolete checklist entries as optional/auditable, but remove them as blockers.
  UPDATE public.deal_requirements r SET rv_required=false
    FROM public.deal_files d
   WHERE d.id=r.deal_id AND d.kind='Sale'
     AND ((d.representation='listing' AND r.label='Sale report form')
        OR (d.representation='selling' AND r.label='Receipt of funds'));

  UPDATE public.rv_compliance_templates t SET active=false, required=false
   WHERE t.kind='Sale' AND t.phase='firm'
     AND ((t.representation='listing' AND t.label='Sale report form')
       OR (t.representation='selling' AND t.label='Receipt of funds'));
  INSERT INTO public.rv_compliance_templates(brokerage_id,kind,phase,representation,label,required,active,sort_order)
   SELECT b.id,'Sale','firm',v.side,v.label,true,true,v.position
   FROM public.brokerages b CROSS JOIN (VALUES
     ('listing','Receipt of funds',30),('selling','Sale report form',30)
   ) v(side,label,position)
   ON CONFLICT(brokerage_id,kind,phase,representation,label)
   DO UPDATE SET required=true,active=true;
  PERFORM public.rv_seed_deal_compliance(d.id)
    FROM public.deal_files d
    WHERE d.kind='Sale' AND d.rv_stage IN ('Sold','Completed')
      AND d.brokerage_id IS NOT NULL;

 EXECUTE $rv052_fn$CREATE OR REPLACE FUNCTION public.rv_reject_clearly_wrong_doc_verification()
 RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $guard$
 DECLARE filename text;
 BEGIN
  IF NEW.verified AND NEW.document_id IS NOT NULL
     AND coalesce(NEW.rv_phase,'other') IN ('offer','firm','completion') THEN
   SELECT lower(f.name) INTO filename FROM public.deal_documents f
     WHERE f.id=NEW.document_id AND f.deal_id=NEW.deal_id;
   IF filename IS NOT NULL AND (
     filename ~* '(agentexpensesbydate|agentgstreport|cheque[_ .-]*alignment|payroll[_ .-]*report|bank[_ .-]*statement)'
     OR (filename ~* 'internal[_ .-]*commission[_ .-]*(payable[_ .-]*)?statement'
         AND lower(NEW.label)<>'internal commission payable statement (pdf)')
     OR (filename ~* 'commission[_ .-]*instruction[_ .-]*report'
         AND lower(NEW.label) NOT IN ('commission instruction report — cir (pdf)','commission instruction report (cir)'))
     OR (filename ~* 'letter[_ .-]*to[_ .-]*complete' AND lower(NEW.label)<>'lawyer completion letter')
     OR (filename ~* 'brokerage[_ .-]*completion[_ .-]*confirmation'
         AND lower(NEW.label)<>'brokerage completion confirmation (pdf)')
   ) THEN RAISE EXCEPTION 'Unrelated document cannot be verified for: %', NEW.label; END IF;
  END IF;
  RETURN NEW;
 END $guard$ $rv052_fn$;
 EXECUTE 'DROP TRIGGER IF EXISTS rv_check_clearly_wrong_document ON public.deal_requirements';
 EXECUTE 'CREATE TRIGGER rv_check_clearly_wrong_document BEFORE INSERT OR UPDATE OF document_id,verified ON public.deal_requirements FOR EACH ROW EXECUTE FUNCTION public.rv_reject_clearly_wrong_doc_verification()';
END $rv052$;
